         [("Buoyant force", "Fb = rf*Vo*g"), ("Weight", "Wt = ro*Vo*g"), ("Apparent weight", "Wa = Wt - Fb"), ("Fraction submerged", "fs = ro/rf")], ["Fb", "Wt", "Wa", "fs"], {"ro": "600 kg/m^3", "rf": "1000 kg/m^3", "Vo": "2 L"},
