         [("Isothermal work (= heat)", "Wiso = n*R*T*log(V2/V1)"), ("Isobaric work", "Wisb = P*(V2 - V1)"), ("Isobaric heat", "Qisb = (fd + 2)/2*P*(V2 - V1)"), ("Isochoric heat", "Qisc = n*fd*R*dTc/2")], ["Wiso", "Wisb", "Qisb", "Qisc"],
